internal final class ARGSalesOrderInvoiceCreateService
{
    SalesId salesId;
    SalesFormLetter salesFormLetter;    


}

Method.Source:
public ARGSalesOrderInvoiceCreateResponse createSalesOrderInvoice(ARGSalesOrderInvoiceCreateRequest _request)
{            
    ARGSalesOrderInvoiceCreateResponse response = new ARGSalesOrderInvoiceCreateResponse();
    SalesTable salesTable;
    List SAPItemsQtys = new List(Types::String);


    changecompany(_request.parmDataAreaId())
    {
        salesId = _request.parmSalesOrderInvoiceCreateClass().parmSalesId();
        salesTable = SalesTable::find(salesId);

        if (salesTable)
        {
            try
            {
                SAPItemsQtys = this.createInvoiceLines(_request,salesTable);
                if (SAPItemsQtys)
                {
                    response = this.postSalesConfirmation(salesTable);
                    if (response.parmSuccess())
                    {
                        response = this.postSalesPackingSlip(SAPItemsQtys,salesTable);
                        if (response.parmSuccess())
                        {
                            response = this.postSalesInvoice(salesTable);
                        }
                    }
                }
                else
                {
                    response.parmSuccess(false);
                    response.parmErrorMessage(strFmt("The items does not match any of the %1 sales order lines",salesId));
                }
            }

            catch (Exception::CLRError)
            {
                System.Exception interopException = CLRInterop::getLastException();
                response.parmSuccess(false);
                response.parmErrorMessage(interopException.ToString());
            }
        }
    }

    return response;
}

public List createInvoiceLines(ARGSalesOrderInvoiceCreateRequest _request, SalesTable _salesTable)
{
    List lines = new List(Types::String);
    ListIterator   literator;
    ARGSalesOrderInvoiceCreateLineClass salesInvoiceLine;
    SalesLine salesLine;
    List SAPItemsQtys = new List(Types::String);

    lines = _request.parmsalesOrderInvoiceCreateLineClassArray();
    if (lines)
    {
        literator = new ListIterator(lines);
        while (literator.more())
        {
            salesInvoiceLine = literator.value();

            select salesLine
            where salesLine.SalesId == salesId
            join _salesTable
            where _salesTable.SalesId == salesLine.SalesId && salesLine.ItemId == salesInvoiceLine.parmItemId();

            if (salesLine)
            {
                SAPItemsQtys.addEnd(salesLine.ItemId);
                SAPItemsQtys.addEnd(int2Str(salesInvoiceLine.parmQuantity()));
            }

            literator.next();
        }
    }        
    return SAPItemsQtys;
}

public ARGSalesOrderInvoiceCreateResponse postSalesConfirmation(SalesTable _salesTable)
{        
    ARGSalesOrderInvoiceCreateResponse response = new ARGSalesOrderInvoiceCreateResponse();
    ARGCustomBatchJobLog errorLog;

    try
    {
        ttsbegin;
        salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);
        salesFormLetter.update(_salesTable, systemDateGet(), SalesUpdate::All);
        ttscommit;
        response.parmSuccess(true);
    }
    catch (Exception::CLRError)
    {
        System.Exception interopException = CLRInterop::getLastException();
        response.parmSuccess(false);
        response.parmErrorMessage(interopException.ToString());

        errorLog.clear();
        errorLog.CreatedByUser = curUserId();
        errorLog.CreatedDateT = DateTimeUtil::getSystemDateTime();
        errorLog.LogMessage = "Order Confirmation";
        errorLog.SalesOrder = _salesTable.SalesId;
        errorLog.Description =  interopException.ToString();
        errorLog.insert();
    }           
    return response;
}

public ARGSalesOrderInvoiceCreateResponse postSalesPackingSlip(List _SAPItemsQtys, SalesTable _salesTable)
{
    ARGSalesOrderInvoiceCreateResponse response = new ARGSalesOrderInvoiceCreateResponse();
    CustPackingSlipJour custPackingSlipJour;
    SalesFormLetter_PackingSlip     salesFormLetter_PackingSlip;
    ListIterator    literator;
    str sapQtyOfProducts;
    SalesLine salesLine;
    ARGCustomBatchJobLog errorLog;


    literator = new ListIterator(_SAPItemsQtys);
    while (literator.more())
    {
        sapQtyOfProducts = literator.value();

        select firstonly forupdate salesLine
        where salesLine.SalesId == _salesTable.SalesId && salesLine.ItemId == sapQtyOfProducts;

        if (salesLine)
        {
            salesLine = SalesLine::find(salesId,salesLine.LineNum,true);
            literator.next();
            sapQtyOfProducts = literator.value();

            ttsbegin;
            salesLine.SalesDeliverNow = str2Int(sapQtyOfProducts);
            salesLine.setInventDeliverNow();
            salesLine.update();
            ttscommit;
        }
        literator.next();            
    }

    try
    {
        ttsbegin;
        salesFormLetter_PackingSlip = SalesFormLetter::construct(DocumentStatus::PackingSlip);
        salesFormLetter_PackingSlip.update(_salesTable, systemDateGet(), SalesUpdate::DeliverNow, AccountOrder::None, false, false); // Set to true to print the packingslip
        ttscommit;
        response.parmSuccess(true);
    }
    catch (Exception::CLRError)
    {
        System.Exception interopException = CLRInterop::getLastException();
        response.parmSuccess(false);
        response.parmErrorMessage(interopException.ToString());

        errorLog.clear();
        errorLog.CreatedByUser = curUserId();
        errorLog.CreatedDateT = DateTimeUtil::getSystemDateTime();
        errorLog.LogMessage = "Packing Slip";
        errorLog.SalesOrder = _salesTable.SalesId;
        errorLog.Description =  interopException.ToString();
        errorLog.insert();
    }

    return response;

    //if (salesFormLetter_PackingSlip.parmJournalRecord().TableId == tableNum(custPackingSlipJour))
    //{
    //    custPackingSlipJour = salesFormLetter_PackingSlip.parmJournalRecord();
    //    //info(custPackingSlipJour.PackingSlipId);
    //}

}

public ARGSalesOrderInvoiceCreateResponse postSalesInvoice(SalesTable _salesTable)
{
    ARGSalesOrderInvoiceCreateResponse response = new ARGSalesOrderInvoiceCreateResponse();
    ARGCustomBatchJobLog errorLog;

    try
    {
        ttsbegin;
        salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);
        salesFormLetter.update(_salesTable, systemDateGet(), SalesUpdate::PackingSlip);
        ttscommit;

        response.parmDebugMessage(strFmt("Sales order: %1 has been invoiced",_salesTable.SalesId));
        response.parmSuccess(true);
    }
    catch (Exception::CLRError)
    {
        System.Exception interopException = CLRInterop::getLastException();
        response.parmSuccess(false);
        response.parmErrorMessage(interopException.ToString());

        errorLog.clear();
        errorLog.CreatedByUser = curUserId();
        errorLog.CreatedDateT = DateTimeUtil::getSystemDateTime();
        errorLog.LogMessage = "Sales Invoice";
        errorLog.SalesOrder = _salesTable.SalesId;
        errorLog.Description =  interopException.ToString();
        errorLog.insert();
    }


    return response;
}

